/* eslint-env node */

const React = require('react-with-addons');
const d3 = require('d3');
const _ = require('underscore');

const Ticks = React.createClass({
  getDefaultProps() {
    return {
      tickLength: 4,
      labelSpacing: 10,
    };
  },

  getInitialState() {
    return {
      clipPathId: 'clipPath' + _.uniqueId(),
    };
  },

  getXScale() {
    const {width, maxX} = this.props;

    return d3.scale.linear()
      .domain([0, maxX])
      .range([0, width]);
  },

  getYScale() {
    const {height, maxY} = this.props;

    return d3.scale.linear()
      .domain([0, maxY])
      .range([height, 0]);  // inverted
  },

  render() {
    const {axis, numTicks, labelSpacing, tickLength, xScale, yScale, format, finalFormat} = this.props;

    const ticks = {x: xScale, y: yScale}[axis].ticks(numTicks);

    console.log(yScale, tickLength);

    if (axis == 'x') {
      return (
        <g>
          {ticks.map((x, i) => [
            <text key={i}
              x={xScale(x)} y={yScale(0) + labelSpacing}
              style={{textAnchor: 'middle', dominantBaseline: 'hanging'}}>
              {finalFormat && i == ticks.length - 1 ? finalFormat(x) : format(x)}
            </text>,
            <line x1={xScale(x)} y1={yScale(0)} x2={xScale(x)} y2={yScale(0) + tickLength} stroke='black'/>
          ])}
        </g>
      );
    } else if (axis == 'y') {
      return (
        <g>
          {ticks.map((y, i) => [
            <text key={i}
              x={-labelSpacing} y={yScale(y)}
              style={{textAnchor: 'end', dominantBaseline: 'central'}}>
              {finalFormat && i == ticks.length - 1 ? finalFormat(y) : format(y)}
            </text>,
            <line x1={-tickLength} y1={yScale(y)} x2={0} y2={yScale(y)} stroke='black'/>
          ])}
        </g>
      );
    }
  },

});

module.exports = Ticks;



