/* eslint-env node */

const React = require('react-with-addons');
const d3 = require('d3');
const _ = require('underscore');

const TangleText = require('./TangleText');
const data = require('./housingData');
const DataPlot = require('./DataPlot');
const Ticks = require('./Ticks');

require('./__styles__/ChartWithDash.styl');
// require('css!./__styles__/ChartWithDash');

const model = (theta0, theta1) => (x) => theta0 + theta1 * x;
const getCost = (data) => (theta0, theta1) => _.reduce(data.map(({x, y}) => Math.pow(y - model(theta0, theta1)(x), 2)), (x, y) => x + y, 0);

const ChartWithDash = React.createClass({
  getDefaultProps() {
    return {
      showSpecial: false,
      showErrors: false,
    };
  },

  getInitialState() {
    return {
      theta0: 0,
      theta1: 0,
      highlightedErrorIndex: null,
    };
  },

  render() {
    const {showErrors, showSpecial} = this.props;
    const {theta0, theta1, highlightedErrorIndex} = this.state;

    const dataWidth = 400;
    const dataHeight = 400;
    const dataMargins = {
      top: 20,
      bottom: 30,
      left: 100,
      right: 50
    };

    const svgWidth = dataMargins.left + dataWidth + dataMargins.right;
    const svgHeight = dataMargins.top + dataHeight + dataMargins.bottom;

    const specialX = 3200;

    return (
      <div className='rc-ChartWithDash horizontal-box'>
        <div>
          <svg width={svgWidth} height={svgHeight}>
            <g transform={`translate(${dataMargins.left}, ${dataMargins.top})`}>
              <DataPlot
                width={dataWidth} height={dataHeight}
                data={data} theta0={theta0} theta1={theta1}
                specialX={specialX}
                maxX={5000} maxY={800000}
                showErrors={showErrors} showSpecial={showSpecial}
                highlightedErrorIndex={highlightedErrorIndex} />
            </g>
          </svg>
        </div>
        <div style={{minWidth: 600, marginTop: 30}}>
          {this.renderDash()}
        </div>
      </div>
    );
  },

  renderDash() {
    const {showErrors, theta1Mode} = this.props;
    const {theta0, theta1, highlightedErrorIndex} = this.state;

    const cost = getCost(data)(theta0, theta1);

    return (
      <div className='dash'>
        <div style={{fontSize: 40}}>
          &theta;<sub>0</sub> = &nbsp;
          {theta1Mode
           ? <span className='tangle-replacement'>0</span>
           : this.renderTangleText('theta0', {step: 1000})
          } $
        </div>
        <div style={{fontSize: 40}}>
          &theta;<sub>1</sub> = &nbsp;
          {this.renderTangleText('theta1', theta1Mode ? {step: 5, min: 0, max: 400} : {step: 5})} <sup>$</sup>/<sub>sq. ft.</sub>
        </div>
        <br/>
        {!theta1Mode &&
          <div>
            <div style={{fontSize: 30}}>
              y = &theta;<sub>0</sub> + &theta;<sub>1</sub> x
            </div>
            <div style={{fontSize: 30}}>
              <span style={{visibility: 'hidden'}}>y</span> = <span style={{color: '#46f'}}>{this.state.theta0}</span> + <span style={{color: '#46f'}}>{this.state.theta1}</span> x
            </div>
          </div>
        }
        {showErrors &&
          <div className='horizontal-box' style={{alignItems: 'flex-end', marginTop: 30}}>
            <ErrorBars width={300} height={100} maxY={800000 / 2} data={data} theta0={theta0} theta1={theta1}
              highlightedErrorIndex={highlightedErrorIndex} setHighlightedErrorIndex={(x) => this.setState({highlightedErrorIndex: x})}/>
            <div style={{marginLeft: 20}}>
              <div style={{fontSize: 30}}>Total cost:</div>
              <div style={{fontSize: 20}}>{d3.format(',')(Math.round(cost / 1000000000))} billion</div>
            </div>
          </div>
        }
        {theta1Mode &&
          <ErrorPlot data={data} theta1={theta1} maxX={400} maxY={20000000000000}
            width={300} height={100} margins={{left: 110, bottom: 80, right: 20, top: 20}}/>
        }
      </div>
    );
  },

  renderTangleText(stateName, props) {
    return (
      <TangleText
        value={this.state[stateName]}
        onChange={(value) => this.setState({[stateName]: value})}
        onInput={(value) => this.setState({[stateName]: value})}
        format={d3.format(',')} {...props} />
    );
  },
});

const ErrorBars = React.createClass({
  getXScale() {
    const {width, data} = this.props;

    return d3.scale.linear()
      .domain([-1, data.length])
      .range([0, width]);
  },

  render() {
    const {width, height, data, theta0, theta1, maxY, highlightedErrorIndex} = this.props;

    const xScale = this.getXScale();

    const yScale = d3.scale.linear()
      .domain([0, maxY])
      .range([height, 0]);  // inverted

    return (
      <svg ref='svg' width={width} height={height + 20} onMouseMove={this.onMouseMove}>
        {data.map(({x,y}, i) => {
          const deltaY = Math.abs(y - model(theta0, theta1)(x));

          return (
            <g key={i}>
              <line x1={xScale(i)} y1={yScale(0)} x2={xScale(i)} y2={yScale(deltaY)}
                stroke='red' strokeWidth={3}/>
              {deltaY > maxY &&
                <circle cx={xScale(i)} cy={yScale(maxY)} r={4}
                  fill='red' />
              }
              {i == highlightedErrorIndex &&
                <text x={xScale(i)} y={yScale(0) + 3}
                  style={{textAnchor: 'middle', dominantBaseline: 'hanging'}}>
                  {'\u2b06'}
                </text>
              }
            </g>
          );
        })}

      </svg>
    );
  },

  onMouseMove(e) {
    const {setHighlightedErrorIndex} = this.props;
    const xScale = this.getXScale();

    setHighlightedErrorIndex(Math.round(xScale.invert(e.clientX - this.refs.svg.getDOMNode().getBoundingClientRect().left)));
  }
});

const ErrorPlot = React.createClass({
  getInitialState() {
    return {
      maxTheta1Visited: 0
    };
  },

  getXScale() {
    const {width, maxX} = this.props;

    return d3.scale.linear()
      .domain([0, maxX])
      .range([0, width]);
  },

  getYScale() {
    const {height, maxY} = this.props;

    return d3.scale.linear()
      .domain([0, maxY])
      .range([height, 0]);  // inverted
  },

  componentWillReceiveProps(nextProps) {
    const {maxTheta1Visited} = this.state;
    this.setState({maxTheta1Visited: Math.max(maxTheta1Visited, nextProps.theta1)});
  },

  render() {
    const {width, height, margins, data, theta1, maxY} = this.props;
    const {maxTheta1Visited} = this.state;

    const svgWidth = margins.left + width + margins.right;
    const svgHeight = margins.top + height + margins.bottom;

    const xScale = this.getXScale();
    const yScale = this.getYScale();

    const points = _.range(0, maxTheta1Visited, 1)
      .map((theta1) => ({x: theta1, y: getCost(data)(0, theta1)}));

    const pathGen = d3.svg.line()
      .interpolate("linear")
      .x(d => xScale(d.x))
      .y(d => yScale(d.y));

    const cost = getCost(data)(0, theta1);

    const yLabelX = xScale(0) - 80;
    const yLabelY = yScale(maxY / 2);

    return (
      <svg ref='svg' width={svgWidth} height={svgHeight}>
        <g transform={`translate(${margins.left}, ${margins.top})`}>
          <path d={pathGen(points)} stroke='red' fill='none'/>

          <line x1={xScale(theta1)} y1={yScale(0)} x2={xScale(theta1)} y2={yScale(cost)}
            stroke='#46f' strokeWidth={1}/>
          <circle cx={xScale(theta1)} cy={yScale(cost)} r={4} fill='red' />
          <text x={xScale(theta1)} y={yScale(0) + 30}
            style={{textAnchor: 'middle', dominantBaseline: 'hanging', fill: '#46f'}}>
            &theta;1
          </text>

          <Ticks axis='x' xScale={xScale} yScale={yScale} numTicks={5}
            format={d3.format(',')} finalFormat={d3.format(',')} />

          <Ticks axis='y' xScale={xScale} yScale={yScale} numTicks={3}
            format={(y) => Math.round(y / 1000000000)} />

          <text x={yLabelX} y={yLabelY}
            style={{textAnchor: 'middle', dominantBaseline: 'alphabetic'}}
            transform={`rotate(${-90}, ${yLabelX}, ${yLabelY})`}
            >
            Cost (in bil.)
          </text>
        </g>
      </svg>
    );
  },

  onMouseMove(e) {
    const {setHighlightedErrorIndex} = this.props;
    const xScale = this.getXScale();

    setHighlightedErrorIndex(Math.round(xScale.invert(e.clientX - this.refs.svg.getDOMNode().getBoundingClientRect().left)));
  }
});

module.exports = ChartWithDash;



