/* eslint-env node */

const React = require('react-with-addons');
const d3 = require('d3');
const _ = require('underscore');

const Ticks = require('./Ticks');

const model = (theta0, theta1) => (x) => theta0 + theta1 * x;


const DataPlot = React.createClass({
  getInitialState() {
    return {
      clipPathId: 'clipPath' + _.uniqueId(),
    };
  },

  getXScale() {
    const {width, maxX} = this.props;

    return d3.scale.linear()
      .domain([0, maxX])
      .range([0, width]);
  },

  getYScale() {
    const {height, maxY} = this.props;

    return d3.scale.linear()
      .domain([0, maxY])
      .range([height, 0]);  // inverted
  },

  render() {
    const {width, height, data, maxX, showErrors, showSpecial, theta0, theta1, highlightedErrorIndex} = this.props;
    const {clipPathId} = this.state;

    const xScale = this.getXScale();
    const yScale = this.getYScale();

    const regressionLineYLeft = model(theta0, theta1)(0);
    const regressionLineYRight = model(theta0, theta1)(maxX);

    return (
      <g>
        {/* Background & corresponding clip-path */}
        <rect width={width} height={height} fill='#EEEEEE'/>
        <defs>
          <clipPath id={clipPathId}>
            <rect width={width} height={height}/>
          </clipPath>
        </defs>

        {/* Data points (& errors, if desired) */}
        <g clipPath={`url(#${clipPathId})`}>
        {showErrors && data.map(({x, y}, i) => {
          const regressY = model(theta0, theta1)(x);
          const arrowOnTop = regressY < y;

          return (
            <g>
              <line key={i} x1={xScale(x)} y1={yScale(y)} x2={xScale(x)} y2={yScale(regressY)}
                stroke='red' strokeWidth={1} />
              {i == highlightedErrorIndex &&
                <text x={xScale(x)} y={yScale(y) + (arrowOnTop ? -5 : 5)}
                  style={{textAnchor: 'middle', dominantBaseline: arrowOnTop ? 'alphabetic' : 'hanging'}}>
                  {arrowOnTop ? '\u2b07' : '\u2b06'}
                </text>
              }
            </g>
          );
        })}
        </g>
        {data.map(({x, y}, i) =>
          <circle key={i} cx={xScale(x)} cy={yScale(y)} r={2}/>
        )}

        <Ticks axis='x' xScale={xScale} yScale={yScale} numTicks={5}
          format={d3.format(',')} finalFormat={(x) => d3.format(',')(x) + ' sq. ft.'} />

        <Ticks axis='y' xScale={xScale} yScale={yScale} numTicks={10}
          format={(y) => '$' + d3.format(',')(y)} />

        {/* Regression line */}
        <line x1={0} y1={yScale(regressionLineYLeft)} x2={xScale(maxX)} y2={yScale(regressionLineYRight)}
          stroke='#46f' strokeWidth={2} clipPath={`url(#${clipPathId})`}/>

        {showSpecial && this.renderSpecialAnnotation()}

      </g>
    );
  },

  renderSpecialAnnotation() {
    const {specialX, theta0, theta1} = this.props;
    const {clipPathId} = this.state;


    const xScale = this.getXScale();
    const yScale = this.getYScale();

    const specialY = model(theta0, theta1)(specialX);

    return (
      <g clipPath={`url(#${clipPathId})`}>
        <line x1={xScale(specialX)} y1={yScale(0)} x2={xScale(specialX)} y2={yScale(specialY)}
          stroke='#46f' strokeWidth={1} />
        <circle cx={xScale(specialX)} cy={yScale(specialY)} r={4} fill='#46f'/>
      </g>
    );
  }
});

module.exports = DataPlot;



