const React = require('react-with-addons');

const ChartWithDash = require('./ChartWithDash');

var Chart1 = React.createClass({
  propTypes: {
    content: React.PropTypes.object.isRequired
  },

  render() {
    return (
      <div className="rc-Chart1 flex-1">
        <ChartWithDash {...this.props.content}/>
      </div>
    );
  }
});

module.exports = Chart1;



